tool.command:
set +e;
mcdi download --manifest "$manifest_file" --output-dir ./downloads --retry-manifest-out ./retry_manifest.txt
#if $extract_archives
    --extract
#end if
;
MCDI_EXIT=\$?;
if [ -f ./retry_manifest.txt ]; then echo '{"__unnamed_outputs": [{"destination": {"type": "hdas"}, "elements": [{"filename": "retry_manifest.txt", "ext": "txt", "name": "files to retry"}]}]}' > galaxy.json; fi;
exit \$MCDI_EXIT;
